import { createHash, randomBytes } from 'node:crypto';
import { strToU8, zipSync } from 'fflate';
import type { Db } from '../store/db.js';
import { extractDocumentText } from '../vault/text-extraction.js';

/**
 * Local PDF and DOCX export. Files are generated here, on this computer, with no external
 * rendering service. The parser report runs the generated bytes through Career Strike's own
 * best-effort text extractor. That is a local sanity check, not a certification by any named
 * applicant-tracking system and not a prediction of how an employer will read the file.
 */

export type ExportFormat = 'pdf' | 'docx';
export type ExportKind = 'resume' | 'cover_letter';

export const EXPORT_MIME: Readonly<Record<ExportFormat, string>> = {
  pdf: 'application/pdf',
  docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
};

export interface ParserReport {
  format: ExportFormat;
  mime: string;
  sizeBytes: number;
  sha256: string;
  extracted: boolean;
  extractedCharacters: number;
  /** True when the parse saw a body with almost no text — the signature of a scanned PDF. */
  sparse: boolean;
  /** True when the text carries U+0000/U+FFFD/Private-Use-Area — the ToUnicode CMap corruption fingerprint. */
  ligatureCorruption: boolean;
  sourceCharacters: number;
  /** Share of distinct source words of four or more characters found after extraction. */
  wordCoverage: number;
  missingWords: string[];
  /** Deliberately explicit: the report is local parser testing, not ATS certification. */
  basis: 'LOCAL_PARSER_TEST_ONLY';
  note: string;
}

export interface DocumentExport {
  bytes: Buffer;
  filename: string;
  mime: string;
  sha256: string;
  sizeBytes: number;
  format: ExportFormat;
  report: ParserReport;
}

export const sha256 = (bytes: Buffer): string => createHash('sha256').update(bytes).digest('hex');

// ---- PDF ----

/** Map common Unicode punctuation to characters the built-in WinAnsi font can show. */
function winAnsi(text: string): string {
  const replacements: Readonly<Record<string, string>> = {
    '\u2018': "'",
    '\u2019': "'",
    '\u201c': '"',
    '\u201d': '"',
    '\u2013': '-',
    '\u2014': '-',
    '\u2026': '...',
    '\u2022': '-',
    '\u00a0': ' ',
    '\u2192': '->',
  };
  let out = '';
  for (const char of text) {
    const code = char.codePointAt(0)!;
    if (replacements[char] !== undefined) out += replacements[char];
    else if (code === 9) out += '    ';
    else if (code >= 32 && code <= 126) out += char;
    else if (code >= 160 && code <= 255) out += char;
    else out += '?';
  }
  return out;
}

const wrap = (text: string, max = 92): string[] => {
  const lines: string[] = [];
  for (const raw of text.replace(/\r\n?/g, '\n').split('\n')) {
    if (raw.trim() === '') {
      lines.push('');
      continue;
    }
    let current = '';
    for (const word of raw.trim().split(/\s+/)) {
      if (current && current.length + word.length + 1 > max) {
        lines.push(current);
        current = word;
      } else {
        current = current ? `${current} ${word}` : word;
      }
    }
    if (current) lines.push(current);
  }
  return lines;
};

const pdfString = (line: string): string =>
  `(${winAnsi(line).replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)')}) Tj`;

/** A deterministic, uncompressed, text-based PDF that opens in ordinary readers. */
export function renderPdf(title: string, content: string): Buffer {
  const lines = wrap(`${title}\n\n${content}`);
  const perPage = 50;
  const pages: string[][] = [];
  for (let i = 0; i < Math.max(lines.length, 1); i += perPage) pages.push(lines.slice(i, i + perPage));

  const objects: string[] = [];
  const fontId = 3;
  const pageIds = pages.map((_, index) => 4 + index * 2);
  objects[0] = '<< /Type /Catalog /Pages 2 0 R >>';
  objects[1] = `<< /Type /Pages /Kids [${pageIds.map((id) => `${id} 0 R`).join(' ')}] /Count ${pages.length} >>`;
  objects[fontId - 1] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>';

  pages.forEach((pageLines, index) => {
    const pageId = pageIds[index]!;
    const contentId = pageId + 1;
    const body = ['BT', '/F1 10 Tf', '50 792 Td', '13 TL'];
    pageLines.forEach((line, lineIndex) => {
      if (lineIndex > 0) body.push('T*');
      body.push(pdfString(line));
    });
    body.push('ET');
    const stream = `${body.join('\n')}\n`;
    objects[pageId - 1] =
      `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 ${fontId} 0 R >> >> /Contents ${contentId} 0 R >>`;
    objects[contentId - 1] = `<< /Length ${Buffer.byteLength(stream, 'latin1')} >>\nstream\n${stream}endstream`;
  });

  const chunks: Buffer[] = [Buffer.from('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n', 'latin1')];
  let offset = chunks[0]!.length;
  const offsets: number[] = [];
  objects.forEach((object, index) => {
    offsets[index] = offset;
    const serialized = Buffer.from(`${index + 1} 0 obj\n${object}\nendobj\n`, 'latin1');
    chunks.push(serialized);
    offset += serialized.length;
  });
  const xrefOffset = offset;
  const xref = [
    'xref',
    `0 ${objects.length + 1}`,
    '0000000000 65535 f ',
    ...offsets.map((value) => `${String(value).padStart(10, '0')} 00000 n `),
    'trailer',
    `<< /Size ${objects.length + 1} /Root 1 0 R >>`,
    'startxref',
    String(xrefOffset),
    '%%EOF',
    '',
  ].join('\n');
  chunks.push(Buffer.from(xref, 'latin1'));
  return Buffer.concat(chunks);
}

// ---- DOCX ----

const xml = (text: string): string =>
  text
    // XML 1.0 forbids most C0 controls.
    .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g, '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');

/** A minimal WordprocessingML package that ordinary word processors can open. */
export function renderDocx(title: string, content: string): Buffer {
  const paragraphs = `${title}\n${content}`
    .replace(/\r\n?/g, '\n')
    .split('\n')
    .map((line) => (line.trim() ? `<w:p><w:r><w:t xml:space="preserve">${xml(line)}</w:t></w:r></w:p>` : '<w:p/>'))
    .join('');
  const document = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>${paragraphs}<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1134" w:right="1134" w:bottom="1134" w:left="1134"/></w:sectPr></w:body></w:document>`;
  const contentTypes = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>`;
  const rels = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>`;
  return Buffer.from(
    zipSync(
      {
        '[Content_Types].xml': strToU8(contentTypes),
        '_rels/.rels': strToU8(rels),
        'word/document.xml': strToU8(document),
      },
      { level: 6 },
    ),
  );
}

// ---- parser report ----

const words = (text: string): Set<string> =>
  new Set(
    (text.toLowerCase().match(/[\p{L}\p{N}][\p{L}\p{N}+#.-]{3,}/gu) ?? []).map((word) => word.replace(/[.-]+$/g, '')),
  );

export async function parserReport(source: string, bytes: Buffer, format: ExportFormat): Promise<ParserReport> {
  const mime = EXPORT_MIME[format];
  const extracted = await extractDocumentText(mime, bytes);
  const sourceWords = words(source);
  const extractedWords = words(extracted?.text ?? '');
  const missing = [...sourceWords].filter((word) => !extractedWords.has(word));
  return {
    format,
    mime,
    sizeBytes: bytes.length,
    sha256: sha256(bytes),
    extracted: extracted !== null,
    extractedCharacters: extracted?.text?.length ?? 0,
    sparse: extracted?.sparse ?? false,
    ligatureCorruption: extracted?.ligatureCorruption ?? false,
    sourceCharacters: source.length,
    wordCoverage: sourceWords.size === 0 ? 1 : (sourceWords.size - missing.length) / sourceWords.size,
    missingWords: missing.slice(0, 20),
    basis: 'LOCAL_PARSER_TEST_ONLY',
    note: 'Generated locally and parsed by Career Strike’s own text extractor. This is not a test by any named ATS, not a guarantee that an employer’s system will read the file, and not a measure of interview chances.',
  };
}

// ---- export service and audit record ----

export interface ExportInput {
  content: string;
  title: string;
  kind: ExportKind;
  format: ExportFormat;
  source: 'MASTER' | 'VARIANT';
  applicationId?: string | null;
  variantId?: string | null;
  actor?: string;
}

interface ExportRow {
  id: string;
  application_id: string | null;
  variant_id: string | null;
  source: string;
  kind: string;
  format: string;
  filename: string;
  sha256: string;
  size_bytes: number;
  created_by: string;
  created_at: string;
}

export interface ExportHistoryItem {
  id: string;
  applicationId: string | null;
  variantId: string | null;
  source: string;
  kind: string;
  format: ExportFormat;
  filename: string;
  sha256: string;
  sizeBytes: number;
  createdBy: string;
  createdAt: string;
}

const safeBase = (name: string): string =>
  name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 60) || 'career-document';

/** Generate one file and record its hash. The file itself is returned, never stored twice. */
export async function createExport(db: Db, input: ExportInput, now = new Date()): Promise<DocumentExport> {
  const bytes = input.format === 'pdf' ? renderPdf(input.title, input.content) : renderDocx(input.title, input.content);
  const digest = sha256(bytes);
  const filename = `${safeBase(input.title)}-${now.toISOString().slice(0, 10)}.${input.format}`;
  const at = now.toISOString();
  const id = `export_${randomBytes(9).toString('base64url')}`;
  const actor = input.actor ?? 'dashboard';
  db.transaction(() => {
    db.prepare(
      `INSERT INTO document_exports
         (id, application_id, variant_id, source, kind, format, filename, sha256, size_bytes, created_by, created_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    ).run(
      id,
      input.applicationId ?? null,
      input.variantId ?? null,
      input.source,
      input.kind,
      input.format,
      filename,
      digest,
      bytes.length,
      actor,
      at,
    );
    db.prepare('INSERT INTO audit_events (at, actor, action, subject) VALUES (?, ?, ?, ?)').run(
      at,
      actor,
      'document.exported',
      `${id}:${input.format}`,
    );
  })();
  return {
    bytes,
    filename,
    mime: EXPORT_MIME[input.format],
    sha256: digest,
    sizeBytes: bytes.length,
    format: input.format,
    report: await parserReport(input.content, bytes, input.format),
  };
}

export function exportHistory(db: Db, limit = 20): ExportHistoryItem[] {
  return (
    db.prepare('SELECT * FROM document_exports ORDER BY created_at DESC, rowid DESC LIMIT ?').all(limit) as ExportRow[]
  ).map((row) => ({
    id: row.id,
    applicationId: row.application_id,
    variantId: row.variant_id,
    source: row.source,
    kind: row.kind,
    format: row.format as ExportFormat,
    filename: row.filename,
    sha256: row.sha256,
    sizeBytes: row.size_bytes,
    createdBy: row.created_by,
    createdAt: row.created_at,
  }));
}
